using System;using System.IO;using System.Linq;using System.Reflection;using MashBoxSDK.AnimationStudio;using UnityEditor;using UnityEngine;using Object=UnityEngine.Object;
public static class StudioBevelVisualValidation
{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static AnimationStudioWindow owner;static MashBoxStudioViewport view;static StudioModelDocument doc;static double deadline;static int phase;static Mesh[] meshes;
 static StudioModelDocument.Node Cube(string name,Vector3 position){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);var mesh=Object.Instantiate(o.GetComponent<MeshFilter>().sharedMesh);Object.DestroyImmediate(o);return new StudioModelDocument.Node{name=name,mesh=mesh,position=position};}
 public static void Run(){EditorApplication.delayCall+=Begin;}
 static void Begin(){try{doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(Cube("Original",new Vector3(1.4f,0,0)));doc.nodes.Add(Cube("Convex",Vector3.zero));doc.nodes.Add(Cube("Concave",new Vector3(-1.4f,0,0)));meshes=doc.nodes.Select(n=>n.mesh).ToArray();foreach(int i in new[]{1,2}){var t=new StudioMeshCuts(doc.nodes[i]);var selected=t.Faces.SelectMany(f=>Enumerable.Range(0,f.Vertices.Count).Select(e=>(f.Vertices[e],f.Vertices[(e+1)%f.Vertices.Count]))).ToList();t.BevelEdges(doc.nodes[i],selected,new StudioMeshCuts.BevelOptions{Width=.4f,Subdivisions=5,Tension=i==1?1:-1,Junction=i==1?StudioMeshCuts.BevelJunction.Uniform:StudioMeshCuts.BevelJunction.Patch});}owner=ScriptableObject.CreateInstance<AnimationStudioWindow>();typeof(AnimationStudioWindow).GetField("modelingMode",F).SetValue(owner,true);typeof(AnimationStudioWindow).GetField("modelDocument",F).SetValue(owner,doc);typeof(AnimationStudioWindow).GetMethod("OpenViewport",F).Invoke(owner,null);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().Single(v=>v.Studio==owner);view.position=new Rect(0,0,1200,800);view.pivot=Vector3.zero;view.rotation=Quaternion.Euler(20,175,0);view.size=1.6f;view.modelGridVisible=false;deadline=EditorApplication.timeSinceStartup+3;EditorApplication.update+=Tick;}catch(Exception e){Finish(e);}}
 static void Tick(){if(EditorApplication.timeSinceStartup<deadline)return;try{if(phase++==0){view.Repaint();view.SendEvent(new Event{type=EventType.Layout});view.SendEvent(new Event{type=EventType.Repaint});deadline=EditorApplication.timeSinceStartup+.5;return;}var rt=(RenderTexture)typeof(MashBoxStudioViewport).GetField("cachedScene",F).GetValue(view);if(!rt)throw new Exception("Preview image was not cached");var previous=RenderTexture.active;var texture=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false,true);try{RenderTexture.active=rt;texture.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);texture.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath, "../bevel-preview.png")),texture.EncodeToPNG());}finally{RenderTexture.active=previous;Object.DestroyImmediate(texture);}Finish(null);}catch(Exception e){Finish(e);}}
 static void Finish(Exception e){EditorApplication.update-=Tick;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath, "../bevel-visual-result.txt")),e==null?"PASS generated before/convex/concave preview":e.ToString());if(view)view.Close();if(owner)Object.DestroyImmediate(owner);if(meshes!=null)foreach(var mesh in meshes)if(mesh)Object.DestroyImmediate(mesh);if(doc)Object.DestroyImmediate(doc);EditorApplication.Exit(0);}
}

